```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define BACKLOG 5  // Maximum pending connections

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    const char *hello = "Hello from TCP server! Message received: ";

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options to reuse address/port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("Setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Configure server address
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;  // Bind to all interfaces
    address.sin_port = htons(PORT);        // Convert port to network byte order

    // Bind socket to port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Start listening for connections
    if (listen(server_fd, BACKLOG) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d (Press CTRL+C to stop)\n", PORT);

    // Main server loop - handles clients sequentially
    while (1) {
        // Accept incoming connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (errno == EINTR) continue;  // Handle signal interruption gracefully
            perror("Accept failed");
            continue;
        }

        printf("New connection from %s:%d\n", 
               inet_ntoa(address.sin_addr), 
               ntohs(address.sin_port));

        // Clear buffer and receive client message
        memset(buffer, 0, BUFFER_SIZE);
        int valread = read(new_socket, buffer, BUFFER_SIZE - 1);

        if (valread > 0) {
            buffer[valread] = '\0';  // Null-terminate received data
            printf("Received from client: %s\n", buffer);

            // Prepare response (echo with prefix)
            char response[BUFFER_SIZE];
            snprintf(response, BUFFER_SIZE, "%s%s", hello, buffer);

            // Send response to client
            if (send(new_socket, response, strlen(response), 0) < 0) {
                perror("Send failed");
            } else {
                printf("Response sent to client\n");
            }
        } else if (valread == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Read failed");
        }

        // Close client connection
        close(new_socket);
        printf("Connection closed\n\n");
    }

    // Cleanup (unreachable in this loop, but good practice)
    close(server_fd);
    return 0;
}
```

**Key Features:**
1. **Robust Error Handling:** Checks all system calls with descriptive errors
2. **Socket Reuse:** `SO_REUSEADDR` allows immediate restart after termination
3. **Graceful Signal Handling:** Ignores `EINTR` errors during accept() for signal safety
4. **Buffer Safety:** 
   - Leaves space for null-terminator in receive buffer
   - Explicitly null-terminates received data
   - Uses `snprintf` to prevent buffer overflows
5. **Client Information:** Prints client IP and port for each connection
6. **Resource Management:** Properly closes all sockets after use
7. **Clear Output:** Detailed console messages for monitoring server activity

**Compilation & Execution:**
```bash
gcc -o tcp_server tcp_server.c
./tcp_server
```

**Testing with netcat:**
```bash
# In another terminal
echo "Hello Server" | nc 127.0.0.1 8080
```

**Expected Output:**
```
Server listening on port 8080 (Press CTRL+C to stop)
New connection from 127.0.0.1:54321
Received from client: Hello Server
Response sent to client
Connection closed
```

**Important Notes:**
1. **Sequential Handling:** Processes one client at a time (not concurrent). For concurrent handling:
   - Fork a child process per connection (add `fork()` after accept)
   - Use threads (`pthread_create`)
   - Implement `select()`/`poll()`/`epoll` for I/O multiplexing
2. **Security Considerations:**
   - Validate all input data in production use
   - Implement timeouts for client connections
   - Consider binding to specific interfaces instead of `INADDR_ANY`
3. **Platform Compatibility:**
   - Works on Linux/macOS/BSD systems
   - For Windows: Requires Winsock initialization (`WSAStartup`)
4. **Graceful Shutdown:** Add signal handlers (`SIGINT`, `SIGTERM`) for clean shutdown in production

**To extend for concurrent clients (simple fork example):**
Add this after the `accept()` call:
```c
if (fork() == 0) {  // Child process handles client
    close(server_fd);  // Child doesn't need server socket
    // ... communication code ...
    close(new_socket);
    exit(0);
}
close(new_socket);  // Parent closes client socket immediately
```
*(Remember to reap zombie processes with `waitpid()` in parent)*

This implementation provides a solid foundation that balances simplicity with production-ready practices. Modify according to your specific requirements for concurrency, protocol complexity, or security needs.

