               inet_ntoa(address.sin_addr), 
               ntohs(address.sin_port));

        // Clear buffer and receive client message
        memset(buffer, 0, BUFFER_SIZE);
        int valread = read(new_socket, buffer, BUFFER_SIZE - 1);

        if (valread > 0) {
            buffer[valread] = '\0';  // Null-terminate received data
            printf("Received from client: %s\n", buffer);

            // Prepare response (echo with prefix)
            char response[BUFFER_SIZE];
            snprintf(response, BUFFER_SIZE, "%s%s", hello, buffer);

            // Send response to client
            if (send(new_socket, response, strlen(response), 0) < 0) {
                perror("Send failed");
            } else {
                printf("Response sent to client\n");
            }
        } else if (valread == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Read failed");
        }

        // Close client connection
        close(new_socket);
        printf("Connection closed\n\n");
    }

    // Cleanup (unreachable in this loop, but good practice)
    close(server_fd);
    return 0;
}
```

**Key Features:**
1. **Robust Error Handling:** Checks all system calls with descriptive errors
2. **Socket Reuse:** `SO_REUSEADDR` allows immediate restart after termination
3. **Graceful Signal Handling:** Ignores `EINTR` errors during accept() for signal safety
4. **Buffer Safety:** 
   - Leaves space for null-terminator in receive buffer
   - Explicitly null-terminates received data
   - Uses `snprintf` to prevent buffer overflows
5. **Client Information:** Prints client IP and port for each connection
6. **Resource Management:** Properly closes all sockets after use
7. **Clear Output:** Detailed console messages for monitoring server activity

